glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
#if USE_TEXTURE
  uniform sampler2D cc_spriteTexture;
#endif
layout(std140) uniform Constants {
  float u_intensity;
  float u_time;
  float u_progress;
};
float hash (vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise (vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i), b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0)), d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm (vec2 p) {
  float v = 0.0, amp = 0.5;
  for (int i = 0; i < 3; i++) { v += amp * vnoise(p); p *= 2.02; amp *= 0.5; }
  return v;
}
float sdCircle (vec2 p, vec2 c, float r) { return length(p - c) - r; }
float smin (float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}
float gummyBody (vec2 p, float wob, float jig) {
  p.x /= (1.0 + 0.16 * wob);
  p.y /= (1.0 - 0.16 * wob);
  float d = sdCircle(p, vec2(0.0, 0.40), 0.265);
  d = smin(d, sdCircle(p, vec2(-0.205, 0.585 + 0.03 * jig), 0.115), 0.05);
  d = smin(d, sdCircle(p, vec2( 0.205, 0.585 - 0.03 * jig), 0.115), 0.05);
  d = smin(d, sdCircle(p * vec2(1.0, 1.14), vec2(0.0, -0.12), 0.40), 0.17);
  d = smin(d, sdCircle(p, vec2(-0.43, 0.07), 0.155), 0.10);
  d = smin(d, sdCircle(p, vec2( 0.43, 0.07), 0.155), 0.10);
  d = smin(d, sdCircle(p, vec2(-0.22, -0.54), 0.165), 0.10);
  d = smin(d, sdCircle(p, vec2( 0.22, -0.54), 0.165), 0.10);
  return d;
}
vec4 frag () {
  float texA = 1.0;
  #if USE_TEXTURE
    texA = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0).a;
  #endif
  float bloom = smoothstep(0.0, 0.18, u_progress);
  float life  = 1.0 - smoothstep(0.6, 1.0, u_progress);
  float diss  = smoothstep(0.55, 1.0, u_progress);
  vec2 p = (uv0 - 0.5) * 2.0;
  float wob = sin(u_time * 5.2) * exp(-u_time * 0.7);
  float jig = sin(u_time * 7.3 + 1.3);
  float pop = bloom * (1.0 + 0.10 * sin(u_time * 6.0) * exp(-u_time * 1.1));
  vec2 ps = p / max(pop, 0.0001);
  float d = gummyBody(ps, wob, jig);
  float fly = diss * 0.95;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float ang = fi * 2.094395 + u_time * 0.6;
    vec2 dir = vec2(cos(ang), sin(ang) * 1.25);
    vec2 c = dir * fly * (0.55 + 0.12 * fi);
    float r = (0.20 - 0.05 * fi) * (1.0 - 0.4 * diss)
            * (1.0 + 0.18 * sin(u_time * (8.0 + fi) + fi));
    float dd = sdCircle(ps, c, r);
    d = smin(d, dd, 0.05);
  }
  float edgeN = fbm(ps * 3.4 + vec2(0.0, u_time * 1.1)) - 0.5;
  d += edgeN * 0.035;
  float aa = 0.02;
  float body = smoothstep(aa, -aa, d);
  if (body < 0.001 && diss < 0.001) { discard; }
  float depth = smoothstep(0.0, 0.34, -d);
  float caustic = fbm(ps * 2.6 - vec2(0.0, u_time * 0.9));
  caustic = 0.6 + 0.5 * caustic;
  vec3 deepC = vec3(0.62, 0.10, 0.30);
  vec3 thinC = vec3(1.0, 0.78, 0.86);
  vec3 jelly = mix(thinC, deepC, depth);
  jelly *= caustic;
  jelly += vec3(1.0, 0.55, 0.72) * (1.0 - depth) * 0.45 * depth;
  float rim = smoothstep(0.055, 0.0, abs(d + 0.012));
  rim = pow(rim, 1.5);
  vec3 rimC = vec3(1.0, 0.86, 0.72);
  jelly += rimC * rim * 0.5;
  vec2 gp = ps - vec2(-0.16, 0.40 + 0.05 * wob);
  float gloss = smoothstep(0.18, 0.0, length(gp * vec2(1.1, 0.8)));
  gloss *= depth;
  float spark = smoothstep(0.06, 0.0, length(ps - vec2(0.12, 0.10)));
  jelly += vec3(1.0) * (gloss * 0.85 + spark * depth * 0.6);
  vec3 rgb = jelly * color.rgb;
  rgb += vec3(gloss * 0.28 + rim * 0.10);
  rgb *= u_intensity * (0.9 + 0.3 * bloom);
  rgb = rgb / (1.0 + max(rgb - 0.85, vec3(0.0)) * 0.7);
  float bodyA = body * mix(0.82, 1.0, depth);
  float shadow = smoothstep(0.45, 0.0, length((ps - vec2(0.0, -0.62)) * vec2(1.0, 1.7)));
  shadow *= (1.0 - body) * 0.28 * bloom * life;
  rgb = mix(rgb, vec3(0.04, 0.0, 0.03), shadow);
  float alpha = max(bodyA, shadow);
  alpha *= life;
  alpha *= texA * color.a;
  alpha = clamp(alpha, 0.0, 1.0);
  vec4 o = vec4(rgb, alpha);
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

